/// <summary>
/// PaffH 24.01.23
/// </summary>
/// <param name="sender">Common</param>
/// <param name="e">DataEventArgs</param>
[DataEventHandler(tableStr(NDXProdIdentProcedureLine1), DataEventType::ModifiedField)]
public static void NDXProdIdentProcedureLine1_onModifiedField(Common sender, DataEventArgs e)
{
    ModifyFieldEventArgs    event = e as ModifyFieldEventArgs;
    FieldId                 fieldId = event.parmFieldId();
    NDXProdIdentProcedureLine1 nDXProdIdentProcedureLine1 = sender as NDXProdIdentProcedureLine1;

    switch(fieldId)
    {
        case fieldNum(NDXProdIdentProcedureLine1, Freigabe):
            NDXProdIdentProtFreigabe::buildNewEntry(nDXProdIdentProcedureLine1.RecId, nDXProdIdentProcedureLine1.Freigabe);
            break;
    }
}
